long long hash1(long long s) {
    // Use a larger prime modulus to reduce collision probability
    return s * 2654435761LL % 1000000007LL;
}

int main() {
    long long s;
    cin >> s;
    vector<long long> first(s);
    // Use a larger hash table size to minimize collisions
    vector<long long> hashTable(1000000008, 0);
    vector<long long> hashTable2(1000000008, 0);

    // Build hash tables for first word
    for (long long i = 0; i < s; i++) {
        long long temp;
        cin >> temp;
        hashTable[hash1(temp)]++;
        first[i] = temp;
    }

    long long v;
    cin >> v;
    vector<long long> second(v);

    // Build hash tables for second word
    for (long long i = 0; i < v; i++) {
        long long temp;
        cin >> temp;
        hashTable2[hash1(temp)]++;
        second[i] = temp;
    }

    long long maxans = 0;

    // First pass: Match second word against first word's hash
    {
        vector<long long> tempTable = hashTable;
        for (long long i = 0; i < v; i++) {
            long long temp = second[i];
            long long h = hash1(temp);
            if (tempTable[h] > 0) {
                long long ans = 0;
                long long j = i;
                while (j < v && tempTable[hash1(second[j])] > 0) {
                    tempTable[hash1(second[j])]--;
                    ans++;
                    j++;
                }
                maxans = max(maxans, ans);
            }
        }
    }

    long long maxans2 = 0;

    // Second pass: Match first word against second word's hash
    {
        vector<long long> tempTable = hashTable2;
        for (long long i = 0; i < s; i++) {
            long long temp = first[i];
            long long h = hash1(temp);
            if (tempTable[h] > 0) {
                long long ans = 0;
                long long j = i;
                while (j < s && tempTable[hash1(first[j])] > 0) {
                    tempTable[hash1(first[j])]--;
                    ans++;
                    j++;
                }
                maxans2 = max(maxans2, ans);
            }
        }
    }

    // Output the maximum of the two passes
    cout << max(maxans, maxans2);
    return 0;
}
